/**
 * =============================================================================
 * KS-386 — THE KYC IMAGE PAYLOAD IS NEVER WRITTEN
 * =============================================================================
 * Kam ruled 2026-08-14: *"Platform K should not hold the images at all, only
 * the attestation."* Migration 045 made `svc_kyc_images.data` nullable so the
 * write could stop while the row survives as that attestation.
 *
 * WHAT THIS FILE IS, STATED PLAINLY: a SOURCE-STRUCTURAL guard, not a
 * behavioural one. It reads the INSERT statement out of `src/index.ts` and
 * asserts the column list. It does NOT drive a request against a database.
 *
 * ITS CORPUS, NAMED RATHER THAN IMPLIED (KS-386 F-2). This guard reads exactly
 * ONE file: `services/kyc/src/index.ts` — pinned by {@link GUARD_CORPUS} and
 * asserted below, so the corpus cannot quietly shrink or grow. Everything
 * outside that file is invisible to it, and one thing outside it is a real
 * writer today:
 *
 *   - `Blockchain/Dev/scripts/backfill-subject-deks.js:169` —
 *     `UPDATE svc_kyc_images SET user_id = …`, the KS-291 linkage backfill.
 *     It writes `user_id` ONLY and never names `data`, so it does not violate
 *     Kam's ruling — but it IS a second write path, and the "exactly one write
 *     path" cell below is a claim about `index.ts`, not about the repository.
 *
 * A repo-wide sweep on 2026-09-06 (`git grep -a -E '(INSERT INTO|UPDATE)
 * svc_kyc_images'`, whole tree) found exactly those two runtime writers. Use
 * `git grep -a`, never plain grep: a raw NUL byte anywhere in a file makes
 * grep skip the whole file silently (KS-847).
 *
 * ITS OTHER LIMIT, equally plainly: a source guard cannot see a rule stop
 * working while its literal stays on the page. The behavioural proof (an
 * upload driven against a real schema, with the row read back and `data`
 * observed NULL) belongs to the tier-1 gate, which has a stack this unit suite
 * does not.
 *
 * Why not drive the route here: the handler resolves the verification through
 * `rowToVerification`, which pulls in the subject-DEK decryption path. Mocking
 * that surface to reach one INSERT would make a brittle test whose failures
 * would mostly be about the mock.
 * =============================================================================
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * The files this guard reads. Pinned as a literal, not derived from a
 * directory walk: a control that computes the thing it is guarding cannot
 * guard it — deleting an entry would just mean checking fewer entries.
 */
const GUARD_CORPUS = ['index.ts'] as const;

const SRC = readFileSync(join(__dirname, '..', GUARD_CORPUS[0]), 'utf8');

/**
 * Remove comments so the guard matches CODE, never PROSE (KS-386 F-3).
 *
 * Without this, a comment that merely quotes a statement — `// the old
 * INSERT INTO svc_kyc_images (id, data, …)` — is indistinguishable from a
 * second write path, and the guard reds on documentation. That is a guard that
 * punishes explaining itself.
 *
 * Strips, in order: block comments, `--` to end of line (SQL comments inside
 * the template literals), and `//` to end of line. The `//` rule deliberately
 * skips a `//` preceded by `:` so a `https://` inside a string survives.
 *
 * KNOWN LIMIT, stated rather than hidden: this is a lexer's job done with
 * regexes. A `//` or `--` occurring inside a string literal that is not a URL
 * would be stripped too. The CONTROL cell below exists precisely for that
 * failure mode — it asserts the REAL statement still survives stripping, so
 * over-stripping reds here rather than passing silently.
 */
function stripComments(source: string): string {
  return source
    .replace(/\/\*[\s\S]*?\*\//g, ' ')
    .replace(/--[^\n]*/g, ' ')
    .replace(/(^|[^:])\/\/[^\n]*/g, '$1 ');
}

/**
 * Every `INSERT INTO svc_kyc_images (...)` column list found in the CODE.
 *
 * The capture is `([^;]*?)` up to the first `)` that closes the list, rather
 * than the old `([^)]*)`: with comments stripped a `)` inside the list is
 * gone, but the non-greedy form also survives a nested `)` should one ever
 * appear, instead of silently truncating the column list to whatever preceded
 * it — a truncated list would compare unequal and red for the wrong reason.
 */
function insertColumnLists(source: string): string[] {
  const out: string[] = [];
  const re = /INSERT\s+INTO\s+svc_kyc_images\s*\(([^;]*?)\)\s*VALUES/gi;
  let m: RegExpExecArray | null;
  while ((m = re.exec(stripComments(source))) !== null) out.push(m[1]);
  return out;
}

/** Every INSERT/UPDATE against the table, in CODE, normalised for comparison. */
function writeStatements(source: string): string[] {
  const hits = stripComments(source).match(/(INSERT\s+INTO|UPDATE)\s+svc_kyc_images/gi) ?? [];
  return hits.map((w) => w.replace(/\s+/g, ' ').toUpperCase());
}

describe('KS-386 — no KYC image payload is persisted', () => {
  it('CONTROL — the corpus is exactly the one file this guard claims to read', () => {
    // F-2. The docstring above says what this guard can and cannot see. If the
    // corpus changes, that prose becomes wrong — so the corpus is asserted,
    // not just described.
    expect(GUARD_CORPUS).toEqual(['index.ts']);
    expect(SRC.length).toBeGreaterThan(1000);
  });

  it('CONTROL — the reader actually finds an INSERT, so the assertions below are not vacuous', () => {
    // Without this, deleting the INSERT entirely (or renaming the table) would
    // satisfy every assertion in this file by finding nothing to check. It is
    // ALSO the over-stripping control: if `stripComments` ever ate the real
    // statement, this reads 0 and reds here rather than passing everywhere.
    expect(insertColumnLists(SRC).length).toBe(1);
  });

  it('🔴 the INSERT does not name the `data` column', () => {
    // Red-proof, predicted in writing before the tamper: restoring `data` to
    // the column list fails THIS cell and the placeholder cell below —
    // SET = {this cell, the placeholder cell}, COUNT = 2.
    const cols = insertColumnLists(SRC)[0]
      .split(',')
      .map((c) => c.trim())
      .filter(Boolean);
    expect(cols).toEqual(['id', 'mime_type', 'user_id']);
    expect(
      cols,
      'svc_kyc_images.data must never be written again — Kam 2026-08-14, and ' +
        "migration 045's column comment says so on the column itself",
    ).not.toContain('data');
  });

  it('🔴 the INSERT binds exactly three parameters', () => {
    // The column list and the placeholder list are two separate claims; a
    // change that dropped `data` from one and not the other would be a runtime
    // error rather than a green test, and this says which.
    const stmt = /INSERT\s+INTO\s+svc_kyc_images[\s\S]{0,200}?VALUES\s*\(([^)]*)\)/i.exec(
      stripComments(SRC),
    );
    expect(stmt, 'the VALUES list must be findable').not.toBeNull();
    const placeholders = (stmt as RegExpExecArray)[1].match(/\$\d+/g) ?? [];
    expect(placeholders).toEqual(['$1', '$2', '$3']);
  });

  it('🔴 `svc_kyc_images` has exactly ONE write path IN THIS FILE, and it is that INSERT', () => {
    // The cell most likely to catch a real regression, and the one the column
    // list cannot: a SECOND writer added anywhere in this file leaves every
    // assertion above green while payloads start being stored again.
    //
    // F-2: the title says IN THIS FILE on purpose. `scripts/backfill-subject-deks.js`
    // also writes this table (user_id only) and is outside the corpus — see the
    // module docstring. This cell is not a claim about the repository.
    expect(
      writeStatements(SRC),
      'a new INSERT or UPDATE against svc_kyc_images must be reviewed against ' +
        "Kam's ruling before it is added — the column is not written by design",
    ).toEqual(['INSERT INTO SVC_KYC_IMAGES']);
  });

  it('🔴 F-3 — a comment that QUOTES the statement is not counted as a write path', () => {
    // The regression this cell exists for: the guard used to match prose, so
    // documenting the change the ticket made would red the ticket's own guard.
    // Both fixtures carry the real statement plus a comment quoting the old
    // one; the reader must see ONE write path and the LIVE column list.
    const jsStyle = [
      '// KS-386: this used to be INSERT INTO svc_kyc_images (id, data, mime_type)',
      '/* and an older draft said UPDATE svc_kyc_images SET data = $1 */',
      'await query(`INSERT INTO svc_kyc_images (id, mime_type, user_id) VALUES ($1,$2,$3)`);',
    ].join('\n');
    expect(writeStatements(jsStyle)).toEqual(['INSERT INTO SVC_KYC_IMAGES']);
    expect(insertColumnLists(jsStyle)).toEqual(['id, mime_type, user_id']);

    const sqlStyle = [
      '-- the old form was INSERT INTO svc_kyc_images (id, data, mime_type)',
      'await query(`INSERT INTO svc_kyc_images (id, mime_type, user_id) VALUES ($1,$2,$3)`);',
    ].join('\n');
    expect(writeStatements(sqlStyle)).toEqual(['INSERT INTO SVC_KYC_IMAGES']);
  });

  it('🔴 F-3 — a `)` inside a comment in the column list does not truncate it', () => {
    // The old `([^)]*)` capture stopped at the first `)` in the source, so a
    // parenthesis inside an inline comment in the column list silently produced
    // a SHORT column list — which then compared unequal and red for a reason
    // that had nothing to do with `data`.
    const withParenComment = [
      'await query(`INSERT INTO svc_kyc_images (',
      '  id, mime_type, -- (KS-291) the erasure linkage follows',
      '  user_id',
      ') VALUES ($1,$2,$3)`);',
    ].join('\n');
    const cols = insertColumnLists(withParenComment)[0]
      .split(',')
      .map((c) => c.trim())
      .filter(Boolean);
    expect(cols).toEqual(['id', 'mime_type', 'user_id']);
  });

  it('CONTROL — stripComments does NOT eat a url, and DOES eat a real comment', () => {
    // A discriminating pair. If stripping were a no-op the second assertion
    // fails; if it were too greedy the first does. Either way this cell reds
    // rather than the guard passing for the wrong reason.
    expect(stripComments("const d = 'https://docs.secuura.io/errors';")).toContain(
      'https://docs.secuura.io/errors',
    );
    expect(stripComments('const a = 1; // INSERT INTO svc_kyc_images (data)')).not.toContain(
      'svc_kyc_images',
    );
  });

  it('CONTROL — the DELETE paths are untouched, so this is not "no SQL mentions the table"', () => {
    // Erasure still needs its two DELETEs (KS-291). If the guard above were
    // written as "the table is never mentioned", it would demand deleting the
    // erasure path — the opposite of what KS-386 wants.
    const deletes = stripComments(SRC).match(/DELETE\s+FROM\s+svc_kyc_images/gi) ?? [];
    expect(deletes.length).toBe(2);
  });
});
